"""Race conditions, atomicity, and concurrent access patterns."""
import threading
import time
from concurrent.futures import ThreadPoolExecutor

import pytest

from swarm_core.memory_store import MemoryStore


class TestConcurrency:
    def test_concurrent_increment_atomicity(self) -> None:
        """100 threads incrementing same key must yield exact count."""
        store = MemoryStore()
        store.set("counter", b"0")
        iterations = 1000
        threads = 10

        def increment() -> None:
            for _ in range(iterations):
                # Atomic increment operation (must be provided by store)
                store.increment("counter")

        with ThreadPoolExecutor(max_workers=threads) as pool:
            futures = [pool.submit(increment) for _ in range(threads)]
            for f in futures:
                f.result(timeout=10.0)

        assert store.get("counter") == str(iterations * threads).encode()

    def test_read_during_write_consistency(self) -> None:
        """Readers must never see partial writes."""
        store = MemoryStore()
        store.set("key", b"old_value")
        stop_flag = threading.Event()
        errors: list[Exception] = []

        def writer() -> None:
            for i in range(1000):
                store.set("key", f"value_{i}".encode())

        def reader() -> None:
            while not stop_flag.is_set():
                val = store.get("key")
                if val is not None and not (val.startswith(b"value_")):
                    errors.append(AssertionError(f"Corrupt read: {val}"))

        w = threading.Thread(target=writer)
        r = threading.Thread(target=reader)
        r.start()
        w.start()
        w.join(timeout=5.0)
        stop_flag.set()
        r.join(timeout=1.0)
        assert not errors, f"Read-during-write violations: {errors}"

    def test_delete_during_iterate(self) -> None:
        """Iteration must not crash or skip entries when concurrent delete occurs."""
        store = MemoryStore()
        for i in range(100):
            store.set(f"key_{i}", b"value")
        stop_flag = threading.Event()

        def deleter() -> None:
            for i in range(0, 100, 2):
                store.delete(f"key_{i}")
                time.sleep(0.001)

        def iterator() -> None:
            while not stop_flag.is_set():
                try:
                    for key in store.iter_keys():
                        pass  # Must not raise
                except Exception as e:
                    errors.append(e)

        errors: list[Exception] = []
        d = threading.Thread(target=deleter)
        i = threading.Thread(target=iterator)
        i.start()
        d.start()
        d.join(timeout=5.0)
        stop_flag.set()
        i.join(timeout=1.0)
        assert not errors

    def test_write_during_write_last_writer_wins(self) -> None:
        """Concurrent writes must converge to one of the written values."""
        store = MemoryStore()
        store.set("key", b"initial")
        with ThreadPoolExecutor(max_workers=5) as pool:
            futures = [pool.submit(store.set, "key", f"w{i}".encode()) for i in range(5)]
            for f in futures:
                f.result(timeout=2.0)
        final = store.get("key")
        assert final in {f"w{i}".encode() for i in range(5)}